let feedbackPromise: Promise<void> | undefined;

export const hydrateWrongFeedback = () => {
  feedbackPromise ??= import("./wrongFeedback.json").then(({ default: feedback }) => {
    const feedbackById = feedback as Record<string, Record<number, string>>;
    for (const quiz of quizzes) {
      const questionFeedback = feedbackById[quiz.id];
      if (questionFeedback) quiz.wrongFeedback = questionFeedback;
    }
  });
  return feedbackPromise;
};
